<script setup>
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import {useContext} from '../composables/context.js';
import {useAccess} from '../composables/access.js';
import {api} from '../services/accounting.js';
import {reportMoney as money,reportDate as date,downloadCsv} from '../services/report-format.js';
import {errorText} from '../locales/accounting.js';
import {corporateTaxErrors as errors,corporateTaxRows as modelRows} from '../locales/corporate-tax.js';
import {corporateTaxRegimes,emptyCorporateTaxInput} from '../../../shared/corporate-tax.js';
import TaxTabs from '../components/TaxTabs.vue';
import EntryDetail from '../components/EntryDetail.vue';
import TaxJournalPdf from '../components/TaxJournalPdf.vue';
import '../assets/tax.css';
import '../assets/corporate-tax.css';
const {company,exercises,selectedExercise,selectedId,selectExercise}=useContext(),{can}=useAccess();
const result=ref(null),input=ref(emptyCorporateTaxInput()),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),unsaved=ref(false),entryId=ref(null),journalPdf=ref(null),search=ref(''),kind=ref('all'),visible=ref(100);
let generation=0;
const ready=computed(()=>!!result.value&&!loading.value&&!busy.value&&result.value.exercise.id===selectedExercise.value?.id);
const changed=computed(()=>!!result.value&&JSON.stringify(input.value)!==JSON.stringify(result.value.input));
const canExport=computed(()=>ready.value&&!changed.value);
const sourceRows=computed(()=>{
 const term=search.value.trim().toLocaleLowerCase('es-ES');
 return (result.value?.source.records||[]).filter(row=>kind.value==='all'||kind.value==='credits'&&row.is_credit||kind.value==='tax'&&row.is_income_tax||kind.value==='expenses'&&row.parent_code?.startsWith('6')||kind.value==='income'&&row.parent_code?.startsWith('7')).filter(row=>!term||[row.code,row.description,row.account_description,row.entry_description,String(row.number)].some(value=>value?.toLocaleLowerCase('es-ES').includes(term)));
});
const sourceSummary=[['net_result','Resultado contable'],['income_tax_expense','IS contabilizado · Corrección automática'],['before_tax','Resultado antes de impuestos']];
const quotaFields=[['bonuses','Bonificaciones revisadas'],['double_tax_relief','Deducciones por doble imposición revisadas'],['deductions','Deducciones de actividades sujetas al límite conjunto']];
const manualCreditFields=[['withholdings','Retenciones e ingresos a cuenta'],['payment_1','Primer pago fraccionado · Modelo 202'],['payment_2','Segundo pago fraccionado · Modelo 202'],['payment_3','Tercer pago fraccionado · Modelo 202']];
const msg=cause=>errors[cause.code]||errorText(cause);
const query=()=>new URLSearchParams({exercise_id:selectedExercise.value.id});
async function consult(){
 const ticket=++generation;result.value=null;error.value='';notice.value='';loading.value=true;entryId.value=null;journalPdf.value=null;unsaved.value=false;
 if(!selectedExercise.value){loading.value=false;return;}
 try{const data=await api('/tax/corporate?'+query(),{timeoutMs:45000});if(ticket===generation){result.value=data;input.value=structuredClone(data.input);}}
 catch(cause){if(ticket===generation)error.value=msg(cause);}finally{if(ticket===generation)loading.value=false;}
}
async function calculate(save=false){
 if(!ready.value)return;const ticket=++generation;busy.value=true;error.value='';notice.value='';
 try{const data=await api('/tax/corporate/'+(save?'draft':'preview')+'?'+query(),{method:save?'PUT':'POST',body:save?{version:result.value.draft.version,input:input.value}:input.value,timeoutMs:45000});if(ticket===generation){result.value=data;input.value=structuredClone(data.input);unsaved.value=!save;notice.value=save?'Borrador guardado para esta empresa y ejercicio.':'Cálculo actualizado. Guarda el borrador para conservar los criterios.';}}
 catch(cause){if(ticket===generation)error.value=msg(cause);}finally{if(ticket===generation)busy.value=false;}
}
function confirmReview(){input.value.reviewed_source_hash=input.value.confirmed_general?result.value.source_hash:'';}
function addAdjustment(row){
 input.value.adjustments.push({id:crypto.randomUUID(),description:row?(row.description||row.account_description).slice(0,200):'',direction:'increase',kind:'permanent',amount:row?(row.debit!=='0.00'?row.debit:row.credit).replace(/^-/,''):'0.00',source_key:row?.key||'',fingerprint:row?.fingerprint||''});
 unsaved.value=true;
}
function clearStale(){input.value.adjustments=input.value.adjustments.filter(row=>!result.value.stale_adjustments.includes(row.id));input.value.confirmed_general=false;input.value.reviewed_source_hash='';}
function exportCsv(proposal=false){
 const data=result.value,a=value=>({amount:value||'0.00'}),rows=[['Impuesto sobre Sociedades · Modelo 200',data.provisional?'Borrador provisional':'Borrador revisado'],['Empresa',data.company.name,'NIF',data.company.tax_id||''],['Ejercicio',data.period.year,'Desde',data.period.from,'Hasta',data.period.to],['Régimen',corporateTaxRegimes[data.input.regime]],['INCN anterior',data.input.previous_turnover===null?'Pendiente':a(data.input.previous_turnover)],[]];
 if(proposal){rows.push(['Propuesta de liquidación · No registrada',data.settlement_proposal.date],['Cuenta','Descripción','Debe','Haber']);for(const line of data.settlement_proposal.lines)rows.push([line.code,line.description,a(line.debit),a(line.credit)]);for(const issue of data.settlement_proposal.issues)rows.push(['Revisión',errors[issue]||issue]);}
 else{
  rows.push(['Casilla de referencia 2025','Concepto','Importe']);for(const [box,label]of modelRows)rows.push([box,label,a(data.boxes[box])]);
  rows.push(['','Bonificaciones',a(data.summary.bonuses)],['','Doble imposición',a(data.summary.double_tax_relief)],['','Deducciones de actividades',a(data.summary.deductions)],['','Retenciones y pagos a cuenta · '+(data.input.credits_mode==='ledger'?'Movimientos 473':'Desglose manual'),a(data.summary.credits)],[],['Tramo base imponible','Tipo %']);for(const row of data.brackets)rows.push([a(row.base),row.rate]);
  rows.push([],['Ajuste','Sentido','Tipo','Importe','Origen']);for(const row of data.adjustments)rows.push([row.description,row.direction==='increase'?'Aumento':'Disminución',row.kind==='permanent'?'Permanente':'Temporario',a(row.amount),row.stale?'Origen modificado':row.source_key||'Manual']);
  rows.push([],['Fecha','Asiento','Cuenta','Descripción','Debe','Haber','Liquidación IS']);for(const row of data.source.records)rows.push([row.date,row.number,row.code,row.description||row.account_description,a(row.debit),a(row.credit),row.is_settlement?'Sí':'']);
  rows.push([],['Notas',data.input.notes]);for(const issue of data.issues)rows.push(['Revisión',errors[issue]||issue]);
 }
 downloadCsv((proposal?'propuesta-liquidacion-is-':'modelo-200-')+data.period.year+'.csv',rows);
}
function print(){window.print();}
watch(()=>selectedExercise.value?.id,()=>void consult(),{immediate:true});
watch([search,kind],()=>visible.value=100);
onBeforeUnmount(()=>generation++);
</script>
<template>
 <div class="tax-page corporate-tax-page">
  <TaxTabs />
  <div class="page-heading tax-controls"><div><p class="eyebrow">{{ company?.name }}</p><h1>Impuesto sobre Sociedades</h1><p class="muted">Modelo 200 · Preparación anual desde la contabilidad</p></div><div class="actions"><button class="button" :disabled="!canExport" @click="exportCsv(false)">Descargar CSV</button><button class="button" :disabled="!canExport" @click="print">Imprimir / guardar PDF</button><a class="button" href="https://sede.agenciatributaria.gob.es/Sede/procedimientoini/GE04.shtml" target="_blank" rel="noopener noreferrer">Sociedades WEB ↗</a></div></div>
  <form class="filters tax-filters tax-controls" @submit.prevent="consult"><label>Ejercicio<select aria-label="Ejercicio de Sociedades" :value="selectedId" :disabled="busy||loading" @change="selectExercise($event.target.value)"><option v-for="exercise in exercises" :key="exercise.id" :value="exercise.id">{{ exercise.name }} · {{ exercise.status==='closed'?'Cerrado':'Abierto' }}</option></select></label><button class="button" :disabled="loading||busy||!selectedExercise">Consultar contabilidad</button><span v-if="result" class="muted">{{ date(result.period.from) }} — {{ date(result.period.to) }} · {{ result.period.days }} días</span></form>
  <p v-if="error" class="notice error-notice" role="alert">{{ error }}</p><p v-if="notice" class="notice success-note tax-controls" role="status">{{ notice }}</p><p v-if="loading" role="status">Consultando el ejercicio…</p><p v-else-if="!selectedExercise" class="notice">Selecciona un ejercicio para preparar Sociedades.</p>
  <template v-if="result">
   <section class="panel tax-settings tax-controls" @input="unsaved=true" @change="unsaved=true">
    <div class="tax-toolbar"><div><h2>Criterios fiscales del ejercicio</h2><p class="muted">{{ result.draft.version?'Borrador guardado · Versión '+result.draft.version:'Sin borrador guardado' }}</p></div><div class="actions"><span v-if="unsaved||changed" class="muted">Cambios sin guardar</span><button class="button" :disabled="!ready" @click="calculate(false)">Recalcular</button><button v-if="can('accounting_write')" class="button primary" :disabled="!ready" @click="calculate(true)">Guardar borrador IS</button></div></div>
    <fieldset class="is-fieldset" :disabled="!ready"><div class="is-fields"><label>Tipo de entidad / régimen<select v-model="input.regime"><option v-for="(label,key) in corporateTaxRegimes" :key="key" :value="key">{{ label }}</option></select></label><label>INCN del período anterior (€)<input v-model="input.previous_turnover" inputmode="decimal" placeholder="Pendiente de confirmar" aria-label="INCN anterior" /><small>Cifra anualizada; incluye el grupo mercantil cuando corresponda.</small></label></div>
     <p v-if="result.source.previous_turnover?.contiguous" class="is-help">Ventas contabilizadas en {{ result.source.previous_turnover.name }}: {{ money(result.source.previous_turnover.amount) }} €. <button class="button small" @click="input.previous_turnover=result.source.previous_turnover.annualized">Usar importe {{ result.source.previous_turnover.annualized!==result.source.previous_turnover.amount?'anualizado ':'' }}de esta empresa</button> Revisa actividades, ajustes y grupo antes de confirmarlo.</p>
     <label v-if="input.regime==='small'" class="checkbox-label"><input v-model="input.erd_extension" type="checkbox" />Cumple la prórroga legal de entidad de reducida dimensión aunque supere el umbral de cifra de negocios.</label>
     <label v-if="input.regime==='new'" class="checkbox-label"><input v-model="input.new_entity_eligible" type="checkbox" />Nueva entidad con actividad económica que cumple el 15 %: primer período con base positiva o el siguiente.</label>
     <label v-if="input.regime!=='patrimonial'" class="checkbox-label"><input v-model="input.new_loss_exception" type="checkbox" />Entidad de nueva creación: cumple la excepción del límite de BIN en uno de los tres primeros períodos con base positiva (art. 26.3 LIS).</label>
     <label class="checkbox-label"><input v-model="input.consolidated" type="checkbox" />Forma parte de un grupo de consolidación fiscal (requiere cálculo específico).</label>
     <p class="is-help">Tipos generales, microempresa, reducida dimensión, nueva creación y patrimonial verificados para 2024–2026. Los regímenes especiales, normativa foral, cuota mínima, rectificativas e incentivos fuera del límite conjunto requieren revisión específica.</p>
     <h3>Ajustes extracontables</h3><p class="muted">El IS contabilizado en 630, 633 y 638 se corrige automáticamente. Añade aquí las otras diferencias fiscales.</p>
     <div v-if="input.adjustments.length" class="table-wrap"><table class="is-adjustments"><thead><tr><th>Concepto y origen</th><th>Sentido</th><th>Tipo</th><th>Importe (€)</th><th></th></tr></thead><tbody><tr v-for="(row,index) in input.adjustments" :key="row.id"><td><input v-model="row.description" maxlength="200" :aria-label="'Concepto ajuste '+(index+1)" placeholder="Multas, amortización fiscal…" /><small v-if="row.source_key">Vinculado a un movimiento contable</small><strong v-if="result.stale_adjustments.includes(row.id)" class="is-stale">Origen modificado · Excluido del cálculo</strong></td><td><select v-model="row.direction" :aria-label="'Sentido ajuste '+(index+1)"><option value="increase">Aumento</option><option value="decrease">Disminución</option></select></td><td><select v-model="row.kind" :aria-label="'Tipo ajuste '+(index+1)"><option value="permanent">Permanente</option><option value="temporary">Temporario</option></select></td><td><input v-model="row.amount" inputmode="decimal" :aria-label="'Importe ajuste '+(index+1)" /></td><td><button class="button small" :aria-label="'Eliminar ajuste '+(index+1)" @click="input.adjustments.splice(index,1)">Eliminar</button></td></tr></tbody></table></div>
     <div class="actions"><button class="button small" @click="addAdjustment()">Añadir ajuste</button><button v-if="result.stale_adjustments.length" class="button small" @click="clearStale">Retirar ajustes con origen modificado</button></div>
     <h3>Reservas y bases negativas</h3><p class="is-help">Introduce importes con derecho fiscal ya revisado. Se comprueban los límites de base; la dotación, antigüedad y mantenimiento de reservas se revisan en la documentación de la empresa.</p>
     <div class="is-fields"><label>Reserva de capitalización solicitada (€)<input v-model="input.capitalization" inputmode="decimal" /><small>Límite de base: {{ money(result.limits.capitalization) }} €</small></label><label>BIN de ejercicios anteriores disponibles (€)<input v-model="input.losses_available" inputmode="decimal" aria-label="BIN disponibles" /></label><label>Compensación de BIN<select v-model="input.losses_mode"><option value="none">Sin compensar</option><option value="maximum">Máximo permitido</option><option value="manual">Importe manual</option></select><small>Límite aplicable: {{ money(result.limits.losses) }} €</small></label><label v-if="input.losses_mode==='manual'">BIN a compensar (€)<input v-model="input.losses_requested" inputmode="decimal" /></label><label>Nivelación · Reversión / aumento (€)<input v-model="input.leveling_increase" inputmode="decimal" /></label><label>Nivelación · Reducción solicitada (€)<input v-model="input.leveling_decrease" inputmode="decimal" /><small>Límite: {{ money(result.limits.leveling) }} €</small></label></div>
     <h3>Bonificaciones y deducciones</h3><div class="is-fields"><label v-for="[key,label] in quotaFields" :key="key">{{ label }} (€)<input v-model="input[key]" inputmode="decimal" /></label><label>Límite conjunto de deducciones<select v-model="input.deduction_limit"><option value="25">25 %</option><option value="50">50 % · Requiere condiciones legales</option></select><small>Máximo: {{ money(result.limits.deductions) }} €</small></label></div><label v-if="input.deduction_limit==='50'" class="checkbox-label"><input v-model="input.enhanced_deduction_eligible" type="checkbox" />Las deducciones del período que dan derecho al límite incrementado cumplen el requisito del artículo 39.1 LIS.</label>
     <h3>Retenciones y pagos fraccionados</h3><div class="is-fields"><label>Origen de los pagos a cuenta<select v-model="input.credits_mode"><option value="ledger">Movimientos contables · Cuenta 473</option><option value="manual">Desglose manual revisado</option></select></label><label v-for="[key,label] in input.credits_mode==='manual'?manualCreditFields:[]" :key="key">{{ label }} (€)<input v-model="input[key]" inputmode="decimal" /></label></div>
     <p v-if="input.credits_mode==='ledger'" class="is-help">Movimientos netos de 473 en el ejercicio: {{ money(result.source.credits_473) }} €. Se excluyen apertura, cierre, regularización y asientos de liquidación IS detectados. El total combina retenciones y pagos a cuenta; usa el desglose manual si incluye otros impuestos o necesitas repartirlos.</p>
     <label class="is-notes">Notas de la revisión<textarea v-model="input.notes" rows="2" maxlength="2000"></textarea></label><label class="checkbox-label"><input v-model="input.confirmed_general" type="checkbox" @change="confirmReview" />He revisado la contabilidad, la cifra de negocios, el régimen y los requisitos de los ajustes e incentivos. Corresponde una liquidación ordinaria de territorio común.</label>
    </fieldset>
   </section>
   <p v-if="changed" class="notice tax-warning tax-controls">Hay cambios pendientes de calcular. Pulsa Recalcular o Guardar borrador IS para actualizar los importes y las exportaciones.</p>
   <div v-if="result.issues.length" class="notice tax-warning"><strong>Borrador provisional · Revisiones pendientes</strong><ul><li v-for="issue in result.issues" :key="issue">{{ errors[issue]||issue }}</li></ul></div>
   <div class="is-overview"><div v-for="[key,label] in sourceSummary" :key="key" class="panel"><small>{{ label }}</small><strong>{{ money(result.summary[key]) }} €</strong></div></div>
   <section class="vat-model" aria-label="Borrador modelo 200">
    <header class="vat-model-heading"><div><p class="eyebrow">{{ result.provisional?'BORRADOR PROVISIONAL':'BORRADOR REVISADO' }}</p><h2>Impuesto sobre Sociedades</h2><p>Liquidación ordinaria del ejercicio {{ result.period.year }}</p></div><div class="vat-model-number">Modelo<strong>200</strong></div></header>
    <div class="vat-identification"><div><small>NIF</small><strong>{{ result.company.tax_id||'Pendiente' }}</strong></div><div><small>Razón social</small><strong>{{ result.company.name }}</strong></div><div><small>Ejercicio</small><strong>{{ result.period.year }}</strong></div><div><small>Estado</small><strong>{{ result.exercise.status==='closed'?'Cerrado':'Abierto' }}</strong></div></div><p class="vat-period">{{ date(result.period.from) }} — {{ date(result.period.to) }} · {{ corporateTaxRegimes[result.input.regime] }}</p>
    <div class="vat-section"><h3>Base imponible y cuota</h3><div v-for="[box,label] in modelRows.filter(row=>!['00611','00621'].includes(row[0]))" :key="box" class="vat-total"><span>{{ label }}</span><div class="vat-static-box"><small>{{ box }}</small><strong>{{ money(result.boxes[box]) }}</strong></div></div>
     <div class="is-rate-detail">Tipo aplicado: <span v-for="(bracket,index) in result.brackets" :key="index">{{ index?' + ':'' }}{{ money(bracket.base) }} € × {{ bracket.rate.replace('.',',') }} %</span></div>
     <div class="vat-total"><span>Retenciones y pagos fraccionados · {{ result.input.credits_mode==='ledger'?'Movimientos 473':'Desglose manual' }}</span><div class="vat-static-box"><strong>{{ money(result.summary.credits) }}</strong></div></div>
     <div class="vat-total vat-result"><div><strong>{{ result.result_kind==='pay'?'Resultado a ingresar':result.result_kind==='refund'?'Resultado a devolver':'Resultado cero' }}</strong><p>{{ result.provisional?'Pendiente de las revisiones indicadas':'Borrador preparado para completar la declaración' }}</p></div><div class="vat-static-box"><small>00621</small><strong>{{ money(result.result) }} €</strong></div></div><p class="is-help">BIN pendientes: {{ money(result.losses.remaining) }} € · Base negativa generada en este ejercicio: {{ money(result.losses.generated) }} €</p>
    </div>
    <footer class="vat-model-footer"><strong>DOCUMENTO DE TRABAJO · NO PRESENTADO</strong><p>Casillas de referencia del modelo 200 de 2025. CSV y PDF sirven para preparar la declaración; completa los datos censales, el balance y los desgloses necesarios en Sociedades WEB. Este apartado no genera el archivo oficial .200 ni envía la declaración.</p><p><a href="https://sede.agenciatributaria.gob.es/Sede/impuesto-sobre-sociedades/que-base-imponible-se-determina-sociedades/tipo-impositivo.html" target="_blank" rel="noopener noreferrer">Tipos de gravamen · AEAT</a> · <a href="https://sede.agenciatributaria.gob.es/Sede/procedimientoini/GE04.shtml" target="_blank" rel="noopener noreferrer">Modelo 200 · AEAT</a></p></footer>
   </section>
   <details class="panel tax-settings is-settlement" open><summary><strong>Propuesta de asiento de liquidación IS</strong></summary><p class="muted">Propuesta para revisar y registrar en Asientos. {{ date(result.settlement_proposal.date) }} · {{ result.settlement_proposal.description }}</p><p v-for="issue in result.settlement_proposal.issues" :key="issue" class="notice">{{ errors[issue]||issue }}</p><p v-if="result.settlement_proposal.empty" class="muted">No hay cuota ni pagos a cuenta que liquidar.</p><div v-if="result.settlement_proposal.lines.length" class="table-wrap"><table><thead><tr><th>Cuenta</th><th>Descripción</th><th class="amount">Debe</th><th class="amount">Haber</th></tr></thead><tbody><tr v-for="(line,index) in result.settlement_proposal.lines" :key="index"><td>{{ line.code }}</td><td>{{ line.description }}</td><td class="amount">{{ money(line.debit) }}</td><td class="amount">{{ money(line.credit) }}</td></tr><tr><th colspan="2">Total</th><td class="amount">{{ money(result.settlement_proposal.totals.debit) }}</td><td class="amount">{{ money(result.settlement_proposal.totals.credit) }}</td></tr></tbody></table></div><p v-for="existing in result.settlement_proposal.existing" :key="existing.entry_id"><button class="button small tax-controls" @click="entryId=existing.entry_id">Revisar asiento {{ existing.number }}</button></p><div class="actions tax-controls"><button class="button" :disabled="!canExport||!result.settlement_proposal.lines.length" @click="exportCsv(true)">CSV del asiento propuesto</button><RouterLink class="button" to="/asientos">Ir a Asientos</RouterLink></div></details>
   <section class="panel tax-settings tax-controls" aria-label="Detalle contable IS"><div class="tax-detail-heading"><div><h2>Origen de los importes</h2><p class="muted">{{ sourceRows.length }} movimientos · Consulta el asiento o su diario original.</p></div><RouterLink class="button" to="/perdidas-ganancias">Ver Pérdidas y Ganancias</RouterLink></div><div class="is-fields"><label>Buscar movimiento<input v-model="search" type="search" placeholder="Cuenta, concepto o asiento" /></label><label>Mostrar<select v-model="kind"><option value="all">Todos los movimientos</option><option value="expenses">Gastos · Grupo 6</option><option value="income">Ingresos · Grupo 7</option><option value="tax">Impuesto sobre beneficios</option><option value="credits">Retenciones y pagos · 473</option></select></label></div><div class="table-wrap"><table><thead><tr><th>Fecha / asiento</th><th>Cuenta</th><th>Concepto</th><th class="amount">Debe</th><th class="amount">Haber</th><th></th></tr></thead><tbody><tr v-for="row in sourceRows.slice(0,visible)" :key="row.key"><td>{{ date(row.date) }}<br /><button class="button small" @click="entryId=row.entry_id">Asiento {{ row.number }}</button></td><td>{{ row.code }}<small>{{ row.account_description }}</small></td><td>{{ row.description }}<small v-if="row.is_settlement">Liquidación IS detectada</small></td><td class="amount">{{ money(row.debit) }}</td><td class="amount">{{ money(row.credit) }}</td><td><div class="actions"><button v-if="row.source_available" class="button small" @click="journalPdf={entryId:row.entry_id,page:row.source_page}">Diario PDF</button><button v-if="!row.is_income_tax&&/^[67]/.test(row.parent_code||'')" class="button small" :disabled="!ready" @click="addAdjustment(row)">Añadir ajuste vinculado</button></div></td></tr><tr v-if="!sourceRows.length"><td colspan="6">No hay movimientos para este filtro.</td></tr></tbody></table></div><button v-if="sourceRows.length>visible" class="button" @click="visible+=100">Mostrar 100 movimientos más</button><p v-if="result.source.diagnostic.unbalanced.length" class="notice error-notice">Asientos descuadrados: {{ result.source.diagnostic.unbalanced.map(row=>row.number).join(', ') }}</p><p v-if="result.source.diagnostic.unclassified.length" class="notice">Cuentas sin clasificar: {{ result.source.diagnostic.unclassified.map(row=>row.code).join(', ') }}</p></section>
  </template>
  <EntryDetail v-if="entryId" :entry-id="entryId" @close="entryId=null" />
  <TaxJournalPdf v-if="journalPdf" :entry-id="journalPdf.entryId" :page="journalPdf.page" title="Diario original · Sociedades" @close="journalPdf=null" />
 </div>
</template>
